W=[
E('puberty','英 /ˈpjuːbəti/；美 /ˈpjuːbərti/','青春期；身体走向性成熟的发育阶段','身体开始从儿童状态向成熟状态过渡。这里重点是生理发育。','经古法语 puberté 并从拉丁 pubertas 借入，最终与 pubes 成熟的、长成的有关。更远来源不确定，没必要硬拆成 pub + erty。',[['拉丁 pubes → pubertas','成熟的 → 成熟年龄、成熟状态'],['古法语 puberté；拉丁 pubertas','英语借词的来源'],['中古英语 puberte → puberty','身体走向性成熟的阶段']],'puberty 说身体发育过程，例如体形、声音和生殖系统逐渐发生变化。它不是生日当天突然开启的一道门，也不等于一个人在心理或社会角色上已经成人。','go through puberty；during puberty；the onset of puberty。','adolescence 更广，常包括青春期前后的心理和社会成长；puberty 更聚焦身体达到性成熟的过程。teenage 看十三到十九岁的年龄，也不能完全画等号。',('The book explains the changes that occur during puberty.','这本书解释青春期发生的变化。'),('The teacher answered the students’ questions about puberty.','老师回答了学生们关于青春期的问题。'),sources=['https://www.etymonline.com/word/puberty','https://medlineplus.gov/puberty.html']),
E('pubescent','/pjuːˈbesənt/','处于青春发育期的；生有细毛的','一条意思是正在长成熟，另一条把目光放到表面新生的细毛上。','最终来自拉丁 pubescere 长成熟的现在分词 pubescens。英语可能经法语借入、直接借自拉丁语，或从较早的 pubescence 反构而来，来源路径不必强定成唯一一种。',[['拉丁 pubescere → pubescens、pubescent-','走向成熟 → 正在走向成熟的'],['英语 pubescent','青春发育期的；后来也用于表面有细毛的生物']],'在人的发育语境里，pubescent 表示正在进入或经历青春期；植物描述里的 pubescent leaves 却是有细毛的叶片，不是在说叶子到了青春期。它在日常谈人时较正式，常见于科普或研究。','pubescent children；pubescent development；pubescent leaves。','pubescent 看发育状态，adolescent 可以更广地说青少年阶段；botanical pubescent 只描述细毛，不能拿人的发育意思硬套植物。',('The study followed a group of pubescent children.','这项研究跟踪了一组处于青春发育期的儿童。'),('The plant has soft, pubescent leaves.','这种植物的叶片柔软，生有细毛。'),sources=['https://www.etymonline.com/word/pubescent','https://en.wiktionary.org/wiki/pubescent#English']),
E('pubic','/ˈpjuːbɪk/','耻骨的；阴部的','它给身体上的一个区域定位，不是泛泛地说青春期。','来自解剖名称 pubis 与形容词结尾 -ic。pubis 源于拉丁 os pubis 耻骨，其中 pubis 是 pubes 阴部、腹股沟区域的词形；这与 pubes 成熟的有历史关联。',[['拉丁 pubes（属格 pubis）→ os pubis','阴部、腹股沟区域 → 耻骨'],['医学拉丁 pubis → 英语 pubic','耻骨 → 与耻骨或阴部区域有关的']],'pubic bone 是骨盆前部的耻骨，pubic hair 是阴毛。词义由它修饰的名词决定：前者说骨头，后者说身体区域的毛发。它是中性的解剖和健康教育用词。','pubic bone；pubic area；pubic hair。','pubic 没有 l，public 有 l，后者表示公共的。两个词的意思差别很大，打字时尤其要看清。',('The diagram labels the pubic bone at the front of the pelvis.','图中标出了骨盆前部的耻骨。'),('The lesson uses neutral terms such as pubic hair.','这节课使用阴毛等中性的身体术语。'),sources=['https://www.etymonline.com/word/pubic','https://en.wiktionary.org/wiki/pubic#English'])]
ROOT=dict(id='C1162',meaning='长成熟；与成熟相关的身体变化',core='PUB = MATURITY',image='从孩子的身体走向成熟：puberty 说这段过程，pubescent 说正在经历它，prepubescent 说尚未进入。',intro='拉丁 pubes 有成熟的、长成的意思，也有与身体区域和成熟征象相关的名词用法。英语留下发育阶段与身体部位两条支线。',forms='pubertas 经法语等途径成为 puberty；pubescere 的分词形式通向 pubescent；pubis 通向 pubic。pub- 只是这一组来源的提示，不是看见相同字母就能通用的万能词根。',branches=[['成长的阶段','puberty','pubescent','prepubescent'],['身体区域','pubic']],contrasts='puberty 侧重生理发育，adolescence 的范围通常更广。pubic 是身体部位相关形容词，public 则是公共的，两者不要混写。',practice='Puberty names a process; pubescent describes someone going through it.\n\npuberty 是一个过程的名称；pubescent 形容正在经历这个过程的人。',words=[x['word'] for x in W]+['prepubescent'],exclude={})
ROOT['branches']=[[x[0],'；'.join(x[1:])] for x in ROOT['branches']]
